def dict_depth(d):
    """
    Calculate the depth of a dictionary, counting nested dictionaries,
    lists, and tuples as contributing to the depth.

    Args:
        d (dict): The dictionary to measure.

    Returns:
        int: The depth of the dictionary.
    """
    if not isinstance(d, dict):
        # Not a dictionary, no depth contribution here
        return 0

    max_child_depth = 0
    for value in d.values():
        if isinstance(value, dict):
            child_depth = dict_depth(value)
            if child_depth > max_child_depth:
                max_child_depth = child_depth
        elif isinstance(value, (list, tuple)):
            # For lists and tuples, check each element for dict depth
            for item in value:
                if isinstance(item, dict):
                    child_depth = dict_depth(item)
                    if child_depth > max_child_depth:
                        max_child_depth = child_depth

    return 1 + max_child_depth


