def solution(a, b, n):
    """
    Finds one solution (x, y) to the equation:
        a*x + b*y = n

    Returns:
        A tuple (x, y) representing one solution if it exists.
        None if no integer solutions exist.

    Uses the Extended Euclidean Algorithm.
    """
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None  # No solution exists

    # Scale the solution of a*x + b*y = g up to a*x + b*y = n
    x = x0 * (n // g)
    y = y0 * (n // g)
    return (x, y)


