def substract_elements(t):
    """
    Recursively subtract all elements in the nested tuple structure.

    Args:
        t (tuple): A nested tuple containing integers or further tuples.

    Returns:
        int: The result of subtracting all elements in order.
    """
    def flatten(nested):
        for el in nested:
            if isinstance(el, tuple):
                yield from flatten(el)
            else:
                yield el

    elements = list(flatten(t))
    if not elements:
        return 0  # or raise an error if empty

    result = elements[0]
    for el in elements[1:]:
        result -= el
    return result


