def remove_column(data, key_to_remove):
    """
    Recursively remove all occurrences of key_to_remove from nested dictionaries and lists.

    Args:
        data (dict, list, or other): The nested data structure to process.
        key_to_remove (str): The key to remove from dictionaries.

    Returns:
        The data structure with all occurrences of key_to_remove removed.
    """
    if isinstance(data, dict):
        # Create a new dict without the key_to_remove
        return {
            k: remove_column(v, key_to_remove)
            for k, v in data.items()
            if k != key_to_remove
        }
    elif isinstance(data, list):
        # Recursively process each item in the list
        return [remove_column(item, key_to_remove) for item in data]
    else:
        # Base case: return the data as is
        return data


