def sort_sublists(collection):
    """
    Given a collection (e.g., list) of subsequences (e.g., lists or tuples),
    return a new collection where each subsequence is sorted.

    Example:
    >>> sort_sublists([[3,1,2], [5,4], [7]])
    [[1, 2, 3], [4, 5], [7]]
    """
    # Detect the type of the outer collection to preserve it
    outer_type = type(collection)

    # Sort each subsequence, preserving its type if possible
    def sort_subseq(subseq):
        sorted_subseq = sorted(subseq)
        # If subsequence is a tuple, return tuple; if list, return list
        if isinstance(subseq, tuple):
            return tuple(sorted_subseq)
        else:
            return sorted_subseq

    sorted_collection = (sort_subseq(subseq) for subseq in collection)

    # Rebuild the outer collection of the same type if possible
    try:
        return outer_type(sorted_collection)
    except TypeError:
        # If outer_type cannot be constructed from an iterator, fallback to list
        return list(sorted_collection)


