def even_binomial_Coeff_Sum(n):
    """
    Calculate the sum of binomial coefficients C(n, k) for even k.

    That is, sum of C(n, 0) + C(n, 2) + C(n, 4) + ... for k even.

    Parameters:
    n (int): The number of items.

