def drop_empty(d):
    """
    Return a new dictionary with all items removed where the value is empty.
    Empty means: None, empty string, empty list, empty tuple, empty dict, empty set.
    Nested dictionaries are cleaned recursively.

    Args:
        d (dict): The input dictionary to clean.

    Returns:
        dict: A new dictionary with empty values removed.
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    def is_empty(value):
        if value is None:
            return True
        if isinstance(value, (str, list, tuple, dict, set)) and len(value) == 0:
            return True
        return False

    cleaned = {}
    for k, v in d.items():
        if isinstance(v, dict):
            nested = drop_empty(v)
            if not is_empty(nested):
                cleaned[k] = nested
        elif not is_empty(v):
            cleaned[k] = v

    return cleaned


